"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  allPages,
  api,
  type Job,
  type Patient,
  type Session,
  type Snapshot,
  type Source,
  type SourceRevision,
} from "@/lib/api";

const message = (error: unknown) =>
  error instanceof Error ? error.message : "Something went wrong.";

export default function Workspace() {
  const [session, setSession] = useState<Session | null>(null);
  const [starting, setStarting] = useState(true);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [patient, setPatient] = useState<Patient | null>(null);
  const [documents, setDocuments] = useState<SourceRevision[]>([]);
  const [jobs, setJobs] = useState<Job[]>([]);
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [snapshotId, setSnapshotId] = useState("");
  const [source, setSource] = useState<Source | null>(null);
  const [spanId, setSpanId] = useState("");
  const [query, setQuery] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const [busy, setBusy] = useState(false);
  const [loadingSource, setLoadingSource] = useState(false);
  const [error, setError] = useState("");
  const [createOpen, setCreateOpen] = useState(false);
  const patientRef = useRef<string | null>(null);
  const sourceRequest = useRef(0);
  const retryImport = useRef<{ signature: string; key: string } | null>(null);

  const loadPatients = useCallback(async () => {
    const values = await allPages<Patient>("/patients");
    setPatients(values);
    const requestedId = new URL(window.location.href).searchParams.get(
      "patient",
    );
    // Never silently switch a bookmarked patient to a different chart.
    setPatient(
      (current) =>
        current ??
        (requestedId
          ? (values.find((value) => value.id === requestedId) ?? null)
          : values.length === 1
            ? values[0]
            : null),
    );
  }, []);

  useEffect(() => {
    api<Session>("/session")
      .then(async (value) => {
        setSession(value);
        await loadPatients();
      })
      .catch((error) => {
        if (!message(error).startsWith("401")) setError(message(error));
      })
      .finally(() => setStarting(false));
  }, [loadPatients]);

  const refresh = useCallback(async (id: string) => {
    const [docs, imports, versions] = await Promise.all([
      allPages<SourceRevision>(`/patients/${id}/documents`),
      allPages<Job>(`/patients/${id}/jobs`),
      api<Snapshot[]>(`/patients/${id}/snapshots`),
    ]);
    if (patientRef.current !== id) return;
    setDocuments(docs);
    setJobs(imports);
    setSnapshots(versions);
  }, []);

  useEffect(() => {
    patientRef.current = patient?.id ?? null;
    sourceRequest.current += 1;
    setSource(null);
    setDocuments([]);
    setJobs([]);
    setSnapshots([]);
    setSnapshotId("");
    setFiles([]);
    setError("");
    setLoadingSource(false);
    setSpanId("");
    if (!patient) return;
    const url = new URL(window.location.href);
    url.searchParams.set("patient", patient.id);
    window.history.replaceState(null, "", url);
    let disposed = false;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      try {
        await refresh(patient.id);
      } catch (error) {
        if (!disposed) setError(message(error));
      }
      if (!disposed) timer = setTimeout(poll, 2000);
    };
    void poll();
    return () => {
      disposed = true;
      clearTimeout(timer);
    };
  }, [patient, refresh]);

  async function signIn() {
    setBusy(true);
    setError("");
    try {
      setSession(await api<Session>("/dev-session", { method: "POST" }));
      await loadPatients();
    } catch (error) {
      setError(message(error));
    } finally {
      setBusy(false);
    }
  }

  async function createPatient(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!session) return;
    setBusy(true);
    setError("");
    const form = new FormData(event.currentTarget);
    try {
      const value = await api<Patient>("/patients", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": session.csrf_token,
        },
        body: JSON.stringify(Object.fromEntries(form)),
      });
      await loadPatients();
      setPatient(value);
      setCreateOpen(false);
    } catch (error) {
      setError(message(error));
    } finally {
      setBusy(false);
    }
  }

  async function upload() {
    if (!session || !patient || !files.length) return;
    const patientId = patient.id;
    setBusy(true);
    setError("");
    const form = new FormData();
    files.forEach((file) => form.append("files", file));
    const signature = JSON.stringify([
      patientId,
      files.map((file) => [file.name, file.size, file.lastModified]),
    ]);
    if (retryImport.current?.signature !== signature)
      retryImport.current = { signature, key: crypto.randomUUID() };
    try {
      await api<Job>(`/patients/${patientId}/imports`, {
        method: "POST",
        headers: {
          "X-CSRF-Token": session.csrf_token,
          "Idempotency-Key": retryImport.current.key,
        },
        body: form,
      });
      retryImport.current = null;
      setFiles([]);
      await refresh(patientId);
    } catch (error) {
      setError(message(error));
    } finally {
      setBusy(false);
    }
  }

  async function openSource(id: string, targetSpan = "") {
    const request = ++sourceRequest.current;
    setLoadingSource(true);
    setError("");
    try {
      const next = await api<Source>(`/source-revisions/${id}`);
      if (sourceRequest.current === request) {
        setSource(next);
        setSpanId(targetSpan);
      }
    } catch (error) {
      if (sourceRequest.current === request) setError(message(error));
    } finally {
      if (sourceRequest.current === request) setLoadingSource(false);
    }
  }

  const selectedSnapshot =
    snapshots.find((value) => value.id === snapshotId) ?? snapshots[0];
  const included = new Set(
    selectedSnapshot?.manifest.map((value) => value.revision_id),
  );
  const visibleDocs = documents.filter(
    (doc) =>
      (!selectedSnapshot || included.has(doc.id)) &&
      `${doc.filename} ${doc.declared_id ?? ""}`
        .toLowerCase()
        .includes(query.toLowerCase()),
  );
  const activeJobs = jobs.filter((job) =>
    ["queued", "running"].includes(job.status),
  );
  const issues = jobs.flatMap((job) =>
    job.uploads.filter((upload) =>
      ["quarantined", "failed"].includes(upload.status),
    ),
  );
  const highlighted = source?.spans.find((span) => span.id === spanId);
  const lines = source?.text.split(/\r\n|[\n\r\v\f\x85\u2028\u2029]/) ?? [];
  if (lines.at(-1) === "") lines.pop();

  return (
    <div className="shell">
      <aside className="sidebar">
        <a className="brand" href="/">
          <span className="brand-icon">e</span>
          <span>
            Evidence<span className="brand-sub">CLINICAL WORKSPACE</span>
          </span>
        </a>
        <div className="nav-label">WORKSPACE</div>
        <div className="nav-item active">
          <span>▤</span> Source library
        </div>
        <div className="nav-item muted">
          <span>◷</span> Clinical timeline <small>Planned</small>
        </div>
        <div className="nav-item muted">
          <span>◇</span> Ask a question <small>Planned</small>
        </div>
        <div className="nav-item muted">
          <span>⊞</span> Experiments <small>Planned</small>
        </div>
        <div className="sidebar-bottom">
          <span className="status-dot" /> Development build
          <p>
            Synthetic records only.
            <br />
            Clinical extraction is not enabled.
          </p>
          <span className="version">SOURCE FOUNDATION · 0.1</span>
        </div>
      </aside>
      <main>
        <header className="topbar">
          <span>
            Patient workspace <span className="slash">/</span>{" "}
            <strong>Source library</strong>
          </span>
          <span className="development">LOCAL DEVELOPMENT</span>
        </header>
        <div className="content">
          <div className="page-heading">
            <div className="eyebrow">START WITH THE RECORD</div>
            <h1>Every source. In context.</h1>
            <p>
              Import records, preserve their history, and inspect the evidence
              behind each account.
            </p>
          </div>
          {error && (
            <div role="alert" className="alert error">
              {error}
            </div>
          )}
          {starting ? (
            <div role="status" className="empty">
              Opening your workspace…
            </div>
          ) : !session ? (
            <section className="welcome panel">
              <div className="empty-icon">▤</div>
              <h2>A clear view of your source records</h2>
              <p>
                This local build supports fictional patient records. Create a
                workspace and inspect original text with exact, stable
                citations.
              </p>
              <button className="primary" disabled={busy} onClick={signIn}>
                {busy ? "Opening…" : "Enter development workspace →"}
              </button>
              <small>
                Development sign-in is shared. Production authentication is not
                enabled.
              </small>
            </section>
          ) : (
            <>
              <section className="patient-bar panel">
                <div className="patient-avatar">
                  {patient?.name
                    .split(" ")
                    .map((part) => part[0])
                    .slice(0, 2)
                    .join("") || "+"}
                </div>
                <div className="patient-picker">
                  <label htmlFor="patient">PATIENT WORKSPACE</label>
                  <select
                    id="patient"
                    value={patient?.id ?? ""}
                    onChange={(event) =>
                      setPatient(
                        patients.find((p) => p.id === event.target.value) ??
                          null,
                      )
                    }
                  >
                    <option value="" disabled>
                      Select a patient
                    </option>
                    {patients.map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.name}
                      </option>
                    ))}
                  </select>
                  {patient && (
                    <small>
                      MRN {patient.mrn} <span>·</span> DOB {patient.birth_date}
                    </small>
                  )}
                </div>
                <button
                  className="secondary"
                  onClick={() => setCreateOpen(!createOpen)}
                >
                  + New patient
                </button>
              </section>
              {(createOpen || !patients.length) && (
                <form className="panel create-form" onSubmit={createPatient}>
                  <h2>Create a patient workspace</h2>
                  <div className="form-fields">
                    <label>
                      Name
                      <input
                        name="name"
                        required
                        maxLength={200}
                        placeholder="Patient name"
                      />
                    </label>
                    <label>
                      Medical record number
                      <input
                        name="mrn"
                        required
                        maxLength={100}
                        pattern="[A-Za-z0-9_-]+"
                        placeholder="MRN from the records"
                      />
                    </label>
                    <label>
                      Date of birth
                      <input name="birth_date" type="date" required />
                    </label>
                    <button className="primary" disabled={busy}>
                      Create workspace
                    </button>
                  </div>
                  <small>
                    Imported records must match this MRN and birth date.
                    Unconfirmed identities are held for review.
                  </small>
                </form>
              )}
              {patient && (
                <>
                  <div className="summary-grid">
                    <div className="panel summary">
                      <span>Source documents</span>
                      <strong>{selectedSnapshot?.manifest.length ?? 0}</strong>
                      <small>Immutable text revisions</small>
                    </div>
                    <div className="panel summary">
                      <span>Import activity</span>
                      <strong>
                        {activeJobs.length
                          ? `${activeJobs.length} active`
                          : "Up to date"}
                      </strong>
                      <small>
                        {jobs.length} import{jobs.length !== 1 ? "s" : ""} in
                        this workspace
                      </small>
                    </div>
                    <div className="panel summary">
                      <span>Clinical abstraction</span>
                      <strong className="pending-label">Not processed</strong>
                      <small>Extraction and QA are coming next</small>
                    </div>
                  </div>
                  <section className="panel import-panel">
                    <div className="import-icon">↥</div>
                    <div>
                      <h2>Add source records</h2>
                      <p>
                        UTF-8 TXT files · up to 10 MiB each, 25 MiB per import,
                        100 files
                      </p>
                    </div>
                    <label className="secondary file-button">
                      Choose files
                      <input
                        aria-label="Choose source files"
                        type="file"
                        accept=".txt,text/plain"
                        multiple
                        onChange={(event) => {
                          setFiles(Array.from(event.target.files ?? []));
                          retryImport.current = null;
                          event.target.value = "";
                        }}
                      />
                    </label>
                    <button
                      className="primary"
                      disabled={!files.length || busy}
                      onClick={upload}
                    >
                      {busy
                        ? "Importing…"
                        : files.length
                          ? `Import ${files.length} file${files.length > 1 ? "s" : ""}`
                          : "Import records"}
                    </button>
                  </section>
                  {files.length > 0 && (
                    <div className="file-preview">
                      Ready to import:{" "}
                      {files.map((file) => file.name).join(", ")}
                    </div>
                  )}
                  {activeJobs.length > 0 && (
                    <div className="alert" role="status">
                      Processing source records. You can close this page and
                      return later.
                    </div>
                  )}
                  {issues.length > 0 && (
                    <details className="alert warning">
                      <summary>
                        {issues.length} file
                        {issues.length !== 1 ? "s need" : " needs"} attention ·
                        source coverage is incomplete
                      </summary>
                      {issues.map((issue) => (
                        <p key={issue.id}>
                          {issue.filename}:{" "}
                          {issue.error_code === "identity_mismatch"
                            ? `The file’s MRN or date of birth does not match ${patient.name} (${patient.mrn}, ${patient.birth_date}). Choose the matching patient workspace and import it there.`
                            : (issue.error_code ?? issue.status).replaceAll(
                                "_",
                                " ",
                              )}
                        </p>
                      ))}
                    </details>
                  )}
                  <section className="panel library">
                    <div className="library-heading">
                      <div>
                        <h2>
                          Source library{" "}
                          <span className="count">{visibleDocs.length}</span>
                        </h2>
                        <p>Original records, preserved exactly as uploaded.</p>
                      </div>
                      <label className="snapshot-picker">
                        Source snapshot
                        <select
                          aria-label="Source snapshot"
                          value={snapshotId}
                          onChange={(event) => {
                            setSnapshotId(event.target.value);
                            setSource(null);
                            sourceRequest.current += 1;
                          }}
                        >
                          <option value="">
                            Latest
                            {snapshots[0] ? ` · v${snapshots[0].sequence}` : ""}
                          </option>
                          {snapshots.map((value) => (
                            <option value={value.id} key={value.id}>
                              v{value.sequence} · {value.manifest.length}{" "}
                              sources
                            </option>
                          ))}
                        </select>
                      </label>
                    </div>
                    {snapshotId && snapshotId !== snapshots[0]?.id && (
                      <div className="historical">
                        Viewing an older source snapshot. Newer imports are not
                        included.
                      </div>
                    )}
                    <div className="evidence-grid">
                      <div className="document-list">
                        <label className="search">
                          <span>⌕</span>
                          <input
                            aria-label="Filter sources"
                            value={query}
                            onChange={(event) => setQuery(event.target.value)}
                            placeholder="Find a source…"
                          />
                        </label>
                        <div className="document-scroll">
                          {visibleDocs.map((doc) => (
                            <button
                              className={`document ${source?.id === doc.id ? "selected" : ""}`}
                              key={doc.id}
                              onClick={() => void openSource(doc.id)}
                            >
                              <span className="doc-icon">TXT</span>
                              <span>
                                <strong>
                                  {doc.declared_id ?? "Text record"}
                                </strong>
                                <span className="filename">{doc.filename}</span>
                                <small>
                                  {doc.line_count} lines <span>·</span>{" "}
                                  {(doc.byte_count / 1024).toFixed(1)} KiB
                                </small>
                              </span>
                              <span className="chevron">›</span>
                            </button>
                          ))}
                          {!visibleDocs.length && (
                            <div className="empty small">
                              {query
                                ? "No sources match your search."
                                : "Your source records will appear here after import."}
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="source-viewer" aria-busy={loadingSource}>
                        {loadingSource ? (
                          <div className="empty" role="status">
                            Opening source…
                          </div>
                        ) : source ? (
                          <>
                            <div className="source-heading">
                              <div>
                                <span className="eyebrow">ORIGINAL SOURCE</span>
                                <h3>{source.declared_id ?? source.filename}</h3>
                                <p>{source.filename}</p>
                              </div>
                              <span className="verified">● Preserved</span>
                            </div>
                            <div className="source-meta">
                              <span>
                                SHA-256{" "}
                                <code title={source.sha256}>
                                  {source.sha256.slice(0, 16)}…
                                </code>
                              </span>
                              <span>{source.line_count} lines</span>
                            </div>
                            <label className="span-picker">
                              Inspect a source block
                              <select
                                aria-label="Source block"
                                value={spanId}
                                onChange={(event) =>
                                  setSpanId(event.target.value)
                                }
                              >
                                <option value="">All source lines</option>
                                {source.spans.map((span) => (
                                  <option key={span.id} value={span.id}>
                                    Lines {span.start_line}–{span.end_line}:{" "}
                                    {span.quote.slice(0, 70)}
                                  </option>
                                ))}
                              </select>
                            </label>
                            <div
                              className="source-lines"
                              tabIndex={0}
                              aria-label="Original source text"
                            >
                              {lines.map((line, i) => (
                                <div
                                  id={`line-${i + 1}`}
                                  key={i}
                                  className={`source-line ${highlighted && i + 1 >= highlighted.start_line && i + 1 <= highlighted.end_line ? "highlighted" : ""}`}
                                >
                                  <span
                                    className="line-number"
                                    aria-hidden="true"
                                  >
                                    {i + 1}
                                  </span>
                                  <span>{line || " "}</span>
                                </div>
                              ))}
                            </div>
                            {highlighted && (
                              <div className="citation-detail">
                                <strong>
                                  Stable citation · lines{" "}
                                  {highlighted.start_line}–
                                  {highlighted.end_line}
                                </strong>
                                <span>
                                  Character offsets [{highlighted.start_char},{" "}
                                  {highlighted.end_char})
                                </span>
                                <a
                                  href={`/api/v1/source-revisions/${source.id}/spans/${highlighted.id}`}
                                  target="_blank"
                                  rel="noreferrer"
                                >
                                  Open citation data ↗
                                </a>
                              </div>
                            )}
                            <div className="source-footer">
                              Blocks are structural text sections. Clinical
                              meaning and document status have not been
                              extracted.
                            </div>
                          </>
                        ) : (
                          <div className="empty source-empty">
                            <div className="empty-icon">▤</div>
                            <h3>Follow the evidence</h3>
                            <p>
                              Select a record to inspect its original text,
                              <br />
                              line numbers, and exact source spans.
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  </section>
                  {jobs.length > 0 && (
                    <details className="panel import-history">
                      <summary>
                        Import history{" "}
                        <span className="count">{jobs.length}</span>
                      </summary>
                      {[...jobs]
                        .sort((a, b) =>
                          b.created_at.localeCompare(a.created_at),
                        )
                        .map((job) => (
                          <div key={job.id} className="job">
                            <div>
                              <strong>
                                {new Date(job.created_at).toLocaleString()}
                              </strong>
                              <span className="job-status">
                                {job.status === "succeeded"
                                  ? "Processing complete"
                                  : job.status}
                              </span>
                              {job.error_code && (
                                <span>
                                  {job.error_code.replaceAll("_", " ")}
                                </span>
                              )}
                            </div>
                            {job.uploads.map((file) => (
                              <div className="upload-row" key={file.id}>
                                <span>{file.filename}</span>
                                <span
                                  className={`upload-status ${file.status}`}
                                >
                                  {file.status}
                                </span>
                              </div>
                            ))}
                          </div>
                        ))}
                    </details>
                  )}
                </>
              )}
              <footer>
                Source-grounded by design <span>·</span> No model inference has
                run{" "}
                <button
                  onClick={async () => {
                    if (!session) return;
                    try {
                      await api<void>("/session", {
                        method: "DELETE",
                        headers: { "X-CSRF-Token": session.csrf_token },
                      });
                      setSession(null);
                      setPatient(null);
                      setPatients([]);
                    } catch (error) {
                      setError(message(error));
                    }
                  }}
                >
                  Sign out
                </button>
              </footer>
            </>
          )}
        </div>
      </main>
    </div>
  );
}
